package com.example.domain.advisor;

/**
 * Diagnostic assessment result generated by polymorphic plant advisors.
 */
public class DiagnosticResult {

    private final String reportedSymptom;
    private final String suspectedCause;
    private final String severityLevel; // Low, Moderate, High, Critical
    private final String recommendedRemedy;
    private final String organicSolution;

    public DiagnosticResult(String reportedSymptom, String suspectedCause, String severityLevel,
                            String recommendedRemedy, String organicSolution) {
        this.reportedSymptom = reportedSymptom;
        this.suspectedCause = suspectedCause;
        this.severityLevel = severityLevel;
        this.recommendedRemedy = recommendedRemedy;
        this.organicSolution = organicSolution;
    }

    public String getReportedSymptom() {
        return reportedSymptom;
    }

    public String suspectedCause() {
        return suspectedCause;
    }

    public String getSuspectedCause() {
        return suspectedCause;
    }

    public String getSeverityLevel() {
        return severityLevel;
    }

    public String getRecommendedRemedy() {
        return recommendedRemedy;
    }

    public String getOrganicSolution() {
        return organicSolution;
    }
}
